SELECT product_num, product_name, product_price, product_img, local_gu_name
FROM product
WHERE local_gu_name = #{localGuName}

SELECT product_num, product_name, product_price, product_img, local_gu_name, category_num
FROM product
WHERE category_num = (
SELECT category_num FROM category WHERE category_name = #{categoryName}
)
